using System;using System.Linq;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.SceneManagement;
namespace XuanwuTools { public static class MaterialLab {
 [MenuItem(Common.Menu+"12 Create material lab from selection")] public static void Create()=>Common.Run(()=>{if(EditorApplication.isPlayingOrWillChangePlaymode)throw new Exception("Not in play mode");var mats=Selection.objects.OfType<Material>().ToArray();if(mats.Length==0||mats.Length>12)throw new Exception("Select 1–12 materials in Project");if(!Common.Confirm("Material lab","Create additive unsaved scene with spheres, plane and neutral directional light? Save separately as Winter_MaterialLab.unity; no global changes."))return;var prior=SceneManager.GetActiveScene();var s=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Additive);SceneManager.SetActiveScene(s);for(int i=0;i<mats.Length;i++){var o=GameObject.CreatePrimitive(PrimitiveType.Sphere);o.name=mats[i].name;o.transform.position=new Vector3((i%4)*2.5f,1,(i/4)*2.5f);o.GetComponent<Renderer>().sharedMaterial=mats[i];}var ground=GameObject.CreatePrimitive(PrimitiveType.Plane);ground.transform.position=new Vector3(3.75f,0,2.5f);var l=new GameObject("Neutral key");l.AddComponent<Light>().type=LightType.Directional;l.transform.rotation=Quaternion.Euler(50,-30,0);var cam=new GameObject("Lab camera");cam.AddComponent<Camera>();cam.transform.position=new Vector3(3.75f,8,-10);cam.transform.LookAt(new Vector3(3.75f,1,2.5f));EditorSceneManager.MarkSceneDirty(s);SceneManager.SetActiveScene(prior);Debug.Log("Lab created additive; save explicitly, close original scene or isolate lab before visual comparison.");});}}
